INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-CTW-C-002', 'R', 'ctw', 'C', '{"topic":"Physical sciences","first":"Astronomers rarely observe planets outside our solar system directly, because their light is overwhelmed by the brightness of the stars they orbit.","parts":[{"t":""},{"t":" "},{"t":"Instead,"},{"t":" "},{"pre":"","keep":"th","n":2,"post":""},{"t":" "},{"t":"rely"},{"t":" "},{"pre":"","keep":"o","n":1,"post":""},{"t":" "},{"t":"indirect"},{"t":" "},{"pre":"","keep":"met","n":4,"post":"."},{"t":" "},{"t":"The"},{"t":" "},{"pre":"","keep":"mo","n":2,"post":""},{"t":" "},{"t":"productive"},{"t":" "},{"pre":"","keep":"tech","n":5,"post":""},{"t":" "},{"t":"measures"},{"t":" "},{"pre":"","keep":"t","n":2,"post":""},{"t":" "},{"t":"slight"},{"t":" "},{"pre":"","keep":"dim","n":4,"post":""},{"t":" "},{"t":"that"},{"t":" "},{"pre":"","keep":"occ","n":3,"post":""},{"t":" "},{"t":"when"},{"t":" "},{"t":"a"},{"t":" "},{"pre":"","keep":"pla","n":3,"post":""},{"t":" "},{"t":"passes"},{"t":" "},{"pre":"","keep":"i","n":1,"post":""},{"t":" "},{"t":"front"},{"t":" "},{"t":"of"},{"t":" "},{"t":"its"},{"t":" "},{"t":"star."},{"t":" "},{"t":"By"},{"t":" "},{"t":"analyzing"},{"t":" "},{"t":"how"},{"t":" "},{"t":"much"},{"t":" "},{"t":"light"},{"t":" "},{"t":"is"},{"t":" "},{"t":"blocked"},{"t":" "},{"t":"and"},{"t":" "},{"t":"how"},{"t":" "},{"t":"often"},{"t":" "},{"t":"the"},{"t":" "},{"t":"dimming"},{"t":" "},{"t":"repeats,"},{"t":" "},{"t":"scientists"},{"t":" "},{"t":"can"},{"t":" "},{"t":"estimate"},{"t":" "},{"t":"both"},{"t":" "},{"t":"the"},{"t":" "},{"t":"size"},{"t":" "},{"t":"of"},{"t":" "},{"t":"the"},{"t":" "},{"t":"planet"},{"t":" "},{"t":"and"},{"t":" "},{"t":"the"},{"t":" "},{"t":"length"},{"t":" "},{"t":"of"},{"t":" "},{"t":"its"},{"t":" "},{"t":"year."},{"t":" "},{"t":"This"},{"t":" "},{"t":"approach"},{"t":" "},{"t":"has"},{"t":" "},{"t":"revealed"},{"t":" "},{"t":"thousands"},{"t":" "},{"t":"of"},{"t":" "},{"t":"distant"},{"t":" "},{"t":"worlds."}]}', '["ey","n","hods","st","nique","he","ming","urs","net","n"]', '["Полное слово: they","Полное слово: on","Полное слово: methods","Полное слово: most","Полное слово: technique","Полное слово: the","Полное слово: dimming","Полное слово: occurs","Полное слово: planet","Полное слово: in"]', '["Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words"]', 1, 'active', 1793386125506, 1793386125506)
