INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-CTW-C-003', 'R', 'ctw', 'C', '{"topic":"History","first":"The spread of printed maps in sixteenth-century Europe transformed how people imagined political territory.","parts":[{"t":""},{"t":" "},{"t":"Earlier"},{"t":" "},{"pre":"","keep":"ma","n":2,"post":""},{"t":" "},{"t":"often"},{"t":" "},{"pre":"","keep":"empha","n":5,"post":""},{"t":" "},{"t":"religious"},{"t":" "},{"pre":"","keep":"si","n":3,"post":""},{"t":" "},{"t":"or"},{"t":" "},{"pre":"","keep":"tr","n":3,"post":""},{"t":" "},{"t":"routes"},{"t":" "},{"pre":"","keep":"rat","n":3,"post":""},{"t":" "},{"t":"than"},{"t":" "},{"pre":"","keep":"cl","n":3,"post":""},{"t":" "},{"t":"borders."},{"t":" "},{"pre":"","keep":"A","n":1,"post":""},{"t":" "},{"t":"printing"},{"t":" "},{"pre":"","keep":"ma","n":2,"post":""},{"t":" "},{"t":"maps"},{"t":" "},{"pre":"","keep":"che","n":4,"post":""},{"t":" "},{"t":"and"},{"t":" "},{"pre":"","keep":"mo","n":2,"post":""},{"t":" "},{"t":"uniform,"},{"t":" "},{"t":"rulers"},{"t":" "},{"t":"began"},{"t":" "},{"t":"to"},{"t":" "},{"t":"use"},{"t":" "},{"t":"them"},{"t":" "},{"t":"to"},{"t":" "},{"t":"define"},{"t":" "},{"t":"and"},{"t":" "},{"t":"defend"},{"t":" "},{"t":"the"},{"t":" "},{"t":"limits"},{"t":" "},{"t":"of"},{"t":" "},{"t":"their"},{"t":" "},{"t":"authority."},{"t":" "},{"t":"Historians"},{"t":" "},{"t":"argue"},{"t":" "},{"t":"that"},{"t":" "},{"t":"the"},{"t":" "},{"t":"familiar"},{"t":" "},{"t":"image"},{"t":" "},{"t":"of"},{"t":" "},{"t":"a"},{"t":" "},{"t":"state"},{"t":" "},{"t":"as"},{"t":" "},{"t":"a"},{"t":" "},{"t":"bounded"},{"t":" "},{"t":"area"},{"t":" "},{"t":"with"},{"t":" "},{"t":"fixed"},{"t":" "},{"t":"lines"},{"t":" "},{"t":"is"},{"t":" "},{"t":"therefore"},{"t":" "},{"t":"partly"},{"t":" "},{"t":"a"},{"t":" "},{"t":"product"},{"t":" "},{"t":"of"},{"t":" "},{"t":"cartographic"},{"t":" "},{"t":"technology"},{"t":" "},{"t":"rather"},{"t":" "},{"t":"than"},{"t":" "},{"t":"a"},{"t":" "},{"t":"natural"},{"t":" "},{"t":"feature"},{"t":" "},{"t":"of"},{"t":" "},{"t":"politics."}]}', '["ps","sized","tes","ade","her","ear","s","de","aper","re"]', '["Полное слово: maps","Полное слово: emphasized","Полное слово: sites","Полное слово: trade","Полное слово: rather","Полное слово: clear","Полное слово: As","Полное слово: made","Полное слово: cheaper","Полное слово: more"]', '["Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words"]', 1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-A-001', 'R', 'rdl', 'A', '{"genre":"chat","doc":{"kind":"chat","msgs":[{"who":"Maya","time":"4:12 PM","text":"Hey! Are you still coming to the study group tonight?"},{"who":"Leo","time":"4:15 PM","text":"Yes, but I''ll be 15 min late. My shift at the café ends at 6."},{"who":"Maya","time":"4:16 PM","text":"No problem. We''re in Room 204 this time, not the library."},{"who":"Leo","time":"4:16 PM","text":"Got it. Should I bring anything?"},{"who":"Maya","time":"4:17 PM","text":"Just your notes from Tuesday''s lecture."}]},"qs":[{"type":"Factual","stem":"Why will Leo be late?","opts":["He missed the bus.","The library is closed.","He forgot his notes.","He has to finish work first."]},{"type":"Factual","stem":"Where will the study group meet?","opts":["In the library","At the café","In the lecture hall","In Room 204"]}]}', '[3,3]', '["Лео пишет: «My shift at the café ends at 6» — у него смена в кафе. Про автобус и закрытую библиотеку в переписке ничего нет, а заметки он только спрашивает, нужно ли брать.","«We''re in Room 204 this time, not the library». Ловушка — библиотека: она упомянута, но с отрицанием not."]', '["Factual","Factual"]', -1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-A-002', 'R', 'rdl', 'A', '{"genre":"notice","doc":{"kind":"notice","head":"Lost & Found — Student Center","paras":["Found on Monday: a blue water bottle with stickers, a black umbrella, and a set of keys on a red keychain.","Items can be picked up at the front desk, 9 a.m.–5 p.m., Monday to Friday. Please bring your student ID.","Items not claimed within 30 days will be donated."]},"qs":[{"type":"Factual","stem":"What is the main purpose of the notice?","opts":["To sell items that nobody wanted","To ask students to donate old items","To announce new opening hours for the Student Center","To tell students where they can collect lost items"]},{"type":"Factual","stem":"What must students bring to pick up an item?","opts":["A receipt","A photo of the item","A note from a teacher","Their student ID"]}]}', '[3,3]', '["Главная цель — сообщить, что найдены вещи и где их забрать. Про пожертвование сказано только как о последствии через 30 дней, это деталь, а не цель.","«Please bring your student ID» — прямо сказано в объявлении."]', '["Factual","Factual"]', -1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-A-003', 'R', 'rdl', 'A', '{"genre":"schedule","doc":{"kind":"table","head":"Campus Gym — Fall Hours","rows":[["Mon / Wed","7:00 a.m. – 10:00 p.m."],["Tue / Thu","7:00 a.m. – 10:00 p.m. (pool closed 12–2 p.m. for swim classes)"],["Friday","7:00 a.m. – 8:00 p.m."],["Saturday","9:00 a.m. – 6:00 p.m."],["Sunday","Closed"]],"foot":"Towels are no longer provided. Please bring your own."},"qs":[{"type":"Factual","stem":"A student wants to swim at 1:00 p.m. On which day can she do this?","opts":["Tuesday","Sunday","Thursday","Wednesday"]},{"type":"Inference","stem":"What is suggested about towels?","opts":["Towels are only needed in the pool.","Towels can be rented at the front desk.","Students must wash the gym''s towels.","The gym used to give towels to students."]}]}', '[3,3]', '["Во вторник и четверг бассейн закрыт с 12 до 2 — значит, в 13:00 плавать нельзя. В воскресенье спортзал закрыт целиком. Остаётся среда.","«No longer provided» — «больше не выдаются». Значит, раньше их выдавали. Это вывод из слов no longer, прямо об этом не сказано."]', '["Factual","Inference"]', -1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-001', 'R', 'rdl', 'B', '{"genre":"email","doc":{"kind":"email","from":"Housing Office","to":"All residents of Oak Hall","subject":"Water shut-off on Thursday","paras":["Dear residents,","Plumbers will replace the main water pipe in Oak Hall on Thursday, March 12. Water will be shut off from 9 a.m. to approximately 3 p.m. Showers and sinks on all floors will be unavailable during this time.","Bottled water will be available in the lobby. Residents who need to shower may use the facilities in Pine Hall, which will not be affected.","We apologize for the inconvenience and appreciate your patience.","Housing Office"]},"qs":[{"type":"Factual","stem":"What is the main purpose of the email?","opts":["To ask residents to report a broken pipe","To invite residents to move to Pine Hall","To announce that Oak Hall will close","To inform residents about a temporary loss of water"]},{"type":"Factual","stem":"According to the email, what can residents do if they need to take a shower?","opts":["Use the showers in Pine Hall","Wait until the evening","Ask the plumbers for permission","Use bottled water from the lobby"]},{"type":"Vocabulary","stem":"The word \"affected\" in the email is closest in meaning to","opts":["repaired","closed","inspected","influenced"],"hlw":"affected"}]}', '[3,0,3]', '["Письмо сообщает, что в четверг на несколько часов отключат воду. Переезжать в Pine Hall никто не предлагает — туда можно сходить в душ.","«Residents who need to shower may use the facilities in Pine Hall». Бутилированная вода в лобби — для питья, не для душа.","Pine Hall «will not be affected» — работы на него не повлияют. Affected = influenced. «Repaired» — частая ловушка: ремонт упоминается в письме, но это не синоним."]', '["Factual","Factual","Vocabulary"]', 0, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-002', 'R', 'rdl', 'B', '{"genre":"social","doc":{"kind":"post","who":"Green Campus Club","handle":"@greencampus","paras":["Swap, don''t shop! Our clothing swap is back on Saturday, 11 a.m.–3 p.m., in the Student Center ballroom.","Bring up to 5 clean items you no longer wear and leave with the same number of \"new\" ones. Leftover clothes will go to a local shelter.","Volunteers needed for setup at 10 — DM us if you can help!"]},"qs":[{"type":"Factual","stem":"What is the post mainly about?","opts":["A sale of new clothes on campus","A new club for students who like fashion","A request for donations to a shelter","An event where students exchange clothing"]},{"type":"Factual","stem":"What will happen to clothes that nobody takes?","opts":["They will be sold.","They will be returned to their owners.","They will be kept for the next swap.","They will be given to a shelter."]},{"type":"Vocabulary","stem":"What does \"DM us\" mean in the post?","opts":["Send us a private message","Come to our office","Donate money to us","Call our manager"],"hlw":"DM us"}]}', '[3,3,0]', '["Swap = обмен: приносишь вещи и уносишь столько же других. Приют упоминается только как место, куда отдадут остатки.","«Leftover clothes will go to a local shelter». Leftover = оставшиеся.","DM — direct message, личное сообщение в соцсети. В Daily Life ETS проверяет неформальный и сокращённый язык."]', '["Factual","Factual","Vocabulary"]', 0, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-003', 'R', 'rdl', 'B', '{"genre":"receipt","doc":{"kind":"receipt","head":"Campus Bookstore","meta":"Receipt #20481 · Oct 3","rows":[["Intro to Psychology (used)","$42.50"],["Lab notebook","$8.00"],["Highlighters, 3-pack","$4.25"],["Subtotal","$54.75"],["Student discount (10%)","–$5.48"],["Total","$49.27"]],"foot":"Paid by card. Returns accepted within 14 days with receipt. Used textbooks may be returned only if unmarked."},"qs":[{"type":"Factual","stem":"How much did the items cost before the discount?","opts":["$42.50","$49.27","$54.75","$5.48"]},{"type":"Inference","stem":"Why might the customer be unable to return the psychology book?","opts":["Because it was bought with a card","Because it was on sale","Because returns are never accepted","Because the customer writes in it"]},{"type":"Factual","stem":"What is true about the purchase?","opts":["The discount applied only to the textbook.","The customer paid in cash.","A discount was taken off the whole subtotal.","The highlighters were free."]}]}', '[2,3,2]', '["До скидки — Subtotal, $54.75. $49.27 — итог после скидки, $5.48 — сама скидка.","Подержанные учебники принимают «only if unmarked» — только без пометок. Если покупатель что-то в нём напишет, вернуть не получится. Это вывод из условия.","10% от $54.75 = $5.48 — значит, скидка посчитана от всей суммы, а не от одного учебника. Оплата — картой (Paid by card)."]', '["Factual","Inference","Factual"]', 0, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-001', 'R', 'rdl', 'C', '{"genre":"email","doc":{"kind":"email","from":"Dr. Elena Moreno","to":"HIST 210 students","subject":"Change to final project requirements","paras":["Dear all,","After reviewing your proposals, I''ve decided to adjust the final project. Rather than submitting a 15-page individual paper, you''ll work in pairs and produce a 10-page report plus a 10-minute presentation in our last session.","I realize some of you have already begun drafting, so if you strongly prefer to continue individually, email me by Friday with a brief justification — I''ll approve reasonable requests.","The deadline remains unchanged.","Best,\nDr. Moreno"]},"qs":[{"type":"Factual","stem":"What is the main purpose of the email?","opts":["To explain a new format for the final project","To cancel the final presentation","To ask students to submit proposals","To announce a later deadline"]},{"type":"Negative Factual","stem":"All of the following are true according to the email EXCEPT:","opts":["Students will give a presentation.","The report will be shorter than the original paper.","The deadline has been extended.","Some students have started writing already."]},{"type":"Inference","stem":"What can be inferred about students who have already started writing?","opts":["They must start a new project.","They will receive extra credit.","They may be allowed to keep working alone.","They have to present first."]}]}', '[0,2,2]', '["Профессор меняет формат: работа в парах, отчёт на 10 страниц и презентация. Дедлайн, наоборот, не меняется.","«The deadline remains unchanged» — срок не продлили. Остальные три утверждения в письме есть.","Можно написать до пятницы с объяснением — разумные просьбы одобрят. Значит, им, скорее всего, разрешат работать в одиночку. Прямо это не обещано — отсюда «may»."]', '["Factual","Negative Factual","Inference"]', 1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-002', 'R', 'rdl', 'C', '{"genre":"chat","doc":{"kind":"chat","group":"Chem 101 study group","msgs":[{"who":"Priya","time":"9:02 AM","text":"Did anyone else get charged twice for the lab fee?"},{"who":"Tom","time":"9:05 AM","text":"Same here. Called the bursar — apparently it''s a system glitch, refunds go out automatically within 5 business days."},{"who":"Priya","time":"9:06 AM","text":"Ugh, I need that money for rent before then."},{"who":"Ana","time":"9:09 AM","text":"You can request an emergency advance at the financial aid office. Took me like 10 min last semester."},{"who":"Priya","time":"9:10 AM","text":"Lifesaver, thanks!"}]},"qs":[{"type":"Factual","stem":"What problem are the students discussing?","opts":["They cannot find the lab.","The financial aid office is closed.","Their rent has increased.","They paid the lab fee two times."]},{"type":"Inference","stem":"Why is Priya worried?","opts":["She may not get her refund in time to pay rent.","She does not know where the bursar''s office is.","She thinks the refund will never come.","She has to pay for the lab again."]},{"type":"Vocabulary","stem":"What does Priya mean when she writes \"Lifesaver\"?","opts":["Ana''s idea is very helpful.","Ana should be more careful.","The situation is dangerous.","She will call for help."],"hlw":"Lifesaver"}]}', '[3,0,0]', '["«Charged twice for the lab fee» — с них дважды списали плату за лабораторию.","Возврат придёт в течение 5 рабочих дней, а деньги нужны на аренду «before then» — раньше. Она не сомневается в возврате, её беспокоит срок.","Lifesaver в разговорной речи — «ты меня спас(ла)», то есть совет очень помог. Буквальное значение («спасатель») здесь не подходит."]', '["Factual","Inference","Vocabulary"]', 1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-003', 'R', 'rdl', 'C', '{"genre":"web","doc":{"kind":"notice","head":"Library Quiet Floors — Updated Policy","paras":["Floors 3 and 4 are designated quiet zones. Brief, whispered conversations are acceptable on Floor 3; Floor 4 is silent at all times. Phone calls must be taken in the stairwells.","Group study rooms on Floor 2 can be reserved online up to 7 days in advance, for a maximum of 3 hours per day per group.","Reservations not claimed within 15 minutes will be released to waiting students."]},"qs":[{"type":"Factual","stem":"Where should students take phone calls?","opts":["On Floor 3","In the group study rooms","In the stairwells","On Floor 4"]},{"type":"Inference","stem":"What will most likely happen if a group arrives 20 minutes late for its reserved room?","opts":["The group will have to pay a fee.","The room may be given to other students.","The group will get an extra hour.","The library will cancel all of the group''s future reservations."]},{"type":"Negative Factual","stem":"According to the policy, which of the following is NOT allowed?","opts":["Whispering on Floor 3","Reserving a room 5 days ahead","Whispering on Floor 4","Using a study room for 2 hours"]}]}', '[2,1,2]', '["«Phone calls must be taken in the stairwells» — только на лестнице.","Бронь, которую не заняли в течение 15 минут, «будет передана ожидающим студентам». 20 минут — больше 15, значит, комнату, скорее всего, отдадут.","На 4-м этаже «silent at all times» — даже шёпот нельзя. Шёпот разрешён только на 3-м. Бронь за 5 дней и на 2 часа укладывается в правила."]', '["Factual","Inference","Negative Factual"]', 1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-001', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"The Mystery of the Purr","paras":[["For a long time, scientists believed that cats purred only when they were happy.","It is true that a relaxed cat often purrs while it is being petted or resting in a warm place.","However, researchers have noticed that cats also purr in very different situations."],["Cats sometimes purr when they are injured, when they are giving birth, or even when they are close to death.","These observations suggest that purring is not simply a sign of pleasure.","One theory proposes that the low vibrations of a purr help bones and muscles heal.","Studies have shown that sounds at similar frequencies can make bones stronger in humans."],["Another explanation focuses on communication.","Kittens begin to purr when they are only a few days old, which lets their mother know that they are safe and feeding well.","Adult cats may keep this behavior because it calms both themselves and the people around them.","Scientists still debate which explanation is correct, and it is possible that purring serves several purposes at once."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, what did scientists believe for a long time?","opts":["Cats purred to communicate with people.","Purring showed that a cat was happy.","Only young cats were able to purr.","Purring helped cats stay warm."]},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that gives evidence supporting the healing theory.","sel":{"p":1}},{"type":"Vocabulary","stem":"The word \"proposes\" in the passage is closest in meaning to","opts":["proves","rejects","suggests","describes"],"hl":{"p":1,"s":2,"w":"proposes"}},{"type":"Reference","stem":"The word \"their\" in paragraph 3 refers to","opts":["kittens","scientists","adult cats","people"],"hl":{"p":2,"s":1,"w":"their"}},{"type":"Inference","stem":"What can be inferred about a cat that purrs while it is injured?","opts":["It is probably feeling pleasure.","It may be purring for a reason other than happiness.","It is trying to call its kittens.","It will soon stop purring completely."]}]}', '[1,3,2,0,1]', '["Первое предложение: «scientists believed that cats purred only when they were happy». Верный вариант — перефраз этой мысли.","Теорию о заживлении вводит третье предложение, а доказательство даёт четвёртое: исследования показали, что звуки похожей частоты укрепляют кости у людей. Ищем именно evidence, а не саму теорию.","Theory proposes — теория предполагает. Proves («доказывает») — ловушка: теория ещё не доказана, учёные спорят.","«Kittens begin to purr …, which lets their mother know» — мать котят. Their относится к kittens.","Абзац 2: такие наблюдения показывают, что мурлыканье — не просто знак удовольствия. Значит, раненая кошка мурлычет, скорее всего, по другой причине. Прямо это о конкретной кошке не сказано — это вывод."]', '["Factual","Select the Sentence","Vocabulary","Reference","Inference"]', -1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-002', 'R', 'rap', 'A', '{"topic":"Business and economics","title":"The Paperback Revolution","paras":[["Until the 1930s, most new books in Britain were sold in hardcover.","They were well made but expensive, so many readers borrowed books from libraries instead of buying them.","Some publishers did print cheap paper editions, but these were usually poorly made and offered light entertainment rather than serious literature."],["In 1935, a publisher named Allen Lane started a company called Penguin.","His idea was simple: he would print serious books with paper covers and sell them for the price of a pack of cigarettes.","Other publishers predicted that the plan would fail.","They believed that cheap books would lower the status of literature and reduce their own profits.","Instead, Penguin sold three million copies in its first year."],["Penguin''s success changed the book trade.","Paperbacks could be sold in railway stations, shops, and newsstands, not only in bookstores.","As a result, reading became a more common activity among working people, who could now afford to build small collections of their own.","Within a few years, other companies had copied the format, and the paperback became a normal part of everyday life."]],"insert":{"p":1,"slots":[1,2,3,5],"sentence":"He is said to have had the idea at a railway station, where he could find nothing good to read for his journey."},"qs":[{"type":"Factual","stem":"According to paragraph 1, why did many readers borrow books from libraries?","opts":["Libraries had more interesting books.","New books were expensive.","Hardcover books were badly made.","Bookstores were far from their homes."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention \"the price of a pack of cigarettes\"?","opts":["To show that Lane also sold cigarettes","To explain how cheap the books were meant to be","To criticize the habits of readers at that time","To compare the quality of books and cigarettes"],"hl":{"p":1,"s":1,"w":"the price of a pack of cigarettes"}},{"type":"Inference","stem":"What can be inferred about other publishers in 1935?","opts":["They did not expect so many people to buy cheap books.","They had already tried selling paperbacks.","They helped Lane start his company.","They lowered the price of hardcover books."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added. Where would the sentence best fit?","insert":true},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are true of paperbacks EXCEPT:","opts":["They were sold in railway stations.","They helped working people build collections.","They were sold only in bookstores.","They changed the book trade."]}]}', '[1,1,0,0,2]', '["«They were well made but expensive, so many readers borrowed books». Badly made — ловушка: в тексте наоборот, well made.","Вопрос о функции фрагмента: автор сравнивает цену книги с ценой пачки сигарет, чтобы показать, насколько дёшево Лейн собирался продавать книги.","Они предсказывали провал, а Penguin продал три миллиона экземпляров за год. Значит, они недооценили спрос на дешёвые книги.","Вставляемое предложение рассказывает, откуда у Лейна появилась идея. Следующее предложение начинается с «His idea was simple» — оно продолжает тему идеи, поэтому вставка идёт сразу после основания компании, перед ним.","В тексте: «not only in bookstores» — не только в книжных. Вариант «only in bookstores» противоречит тексту."]', '["Factual","Rhetorical Purpose","Inference","Insert Text","Negative Factual"]', -1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-001', 'R', 'rap', 'B', '{"topic":"Physical sciences","title":"Urban Heat Islands","paras":[["Cities are often several degrees warmer than the countryside around them, a phenomenon known as the urban heat island effect.","Measurements in some large cities have recorded differences of more than ten degrees between downtown streets and nearby farmland.","The difference is usually greatest at night, when rural areas cool quickly but cities continue to release heat."],["Several features of urban environments contribute to this warming.","Dark surfaces such as asphalt roads and rooftops absorb a large share of the sunlight that reaches them and store it as heat.","Tall buildings trap this heat and block the winds that might otherwise carry it away.","In addition, cars, air conditioners, and factories release heat directly into the air."],["The consequences go beyond discomfort.","Higher temperatures increase the demand for air conditioning, which in turn raises energy consumption and, in many places, air pollution.","During heat waves, elderly residents and people without access to cooling face serious health risks.","To address the problem, some cities are painting roofs white, expanding parks, and planting trees along streets, since vegetation cools the air through the evaporation of water from leaves."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, when is the difference in temperature between cities and rural areas greatest?","opts":["In the early morning","During heat waves","At night","In the middle of the day"]},{"type":"Vocabulary","stem":"The word \"trap\" in the passage is closest in meaning to","opts":["create","hold in","reflect","measure"],"hl":{"p":1,"s":2,"w":"trap"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Because people use more air conditioning when it is hot, energy use rises and pollution often increases.","Air conditioning makes cities hotter, which is the main cause of pollution.","Energy consumption and air pollution are the main reasons why cities are hotter.","When pollution increases, people use air conditioning more often in hot weather."],"simp":{"p":2,"s":1}},{"type":"Rhetorical Purpose","stem":"Why does the author mention \"elderly residents\" in paragraph 3?","opts":["To give an example of people for whom heat can be dangerous","To explain why cities use more air conditioning","To show that older people prefer to live in cities","To argue that cities should build more hospitals"],"hl":{"p":2,"s":2,"w":"elderly residents"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that explains how plants reduce temperatures.","sel":{"p":2}}]}', '[2,1,0,0,3]', '["«The difference is usually greatest at night» — ночью: село остывает быстро, а город продолжает отдавать тепло.","Здания «trap this heat and block the winds that might otherwise carry it away» — удерживают тепло, не дают ему уйти. Trap = hold in.","Цепочка в оригинале: жара → больше кондиционеров → больше энергии → часто больше загрязнения. Вариант A сохраняет эту причинно-следственную цепочку. B и C переворачивают причину и следствие, D меняет порядок звеньев.","Абзац говорит о последствиях жары. Пожилые жители — пример тех, для кого жара — серьёзный риск для здоровья. Это функция примера, а не отдельный аргумент.","Последнее предложение: растительность охлаждает воздух за счёт испарения воды с листьев (evaporation of water from leaves)."]', '["Factual","Vocabulary","Sentence Simplification","Rhetorical Purpose","Select the Sentence"]', 0, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-002', 'R', 'rap', 'B', '{"topic":"Business and economics","title":"Why Prices End in 99","paras":[["Walk into almost any store and you will see prices such as $4.99 or $19.99 rather than $5 or $20.","This practice, known as charm pricing, is so common that many shoppers no longer notice it.","Yet economists and psychologists have found that it can have a measurable effect on what people buy."],["The most widely accepted explanation involves the way people read numbers.","Because we read from left to right, the first digit makes the strongest impression.","A price of $2.99 therefore feels closer to $2 than to $3, even though the difference from $3 is only one cent.","In one experiment, a clothing company found that a dress sold more often at $39 than at $34, a price that was actually lower."],["Charm pricing does not work in every situation, however.","Luxury brands often avoid it because they want customers to associate their products with quality rather than bargains.","For them, a round number such as $200 sends a message of confidence and simplicity.","Retailers must therefore decide whether they want a price to look cheap or to look prestigious."]],"qs":[{"type":"Reference","stem":"The word \"it\" in paragraph 1 refers to","opts":["a store","charm pricing","a price of $5","a shopper"],"hl":{"p":0,"s":1,"w":"it"}},{"type":"Factual","stem":"According to paragraph 2, why does $2.99 seem closer to $2 than to $3?","opts":["Shoppers usually round prices down.","The first digit has the strongest effect on the reader.","Stores display the cents in small print.","People cannot calculate small differences."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention the dress that sold more often at $39 than at $34?","opts":["To show that a price ending in 9 can attract buyers even when it is higher","To explain why clothing is more expensive than other goods","To argue that companies should raise their prices","To show that shoppers always choose the lowest price"]},{"type":"Negative Factual","stem":"According to paragraph 3, which of the following is NOT given as a reason luxury brands avoid charm pricing?","opts":["They want their products to be linked with quality.","Round numbers suggest confidence.","Round numbers are easier for cashiers to process.","They do not want to look like bargains."]},{"type":"Inference","stem":"What can be inferred about a shop that prices a watch at $500 instead of $499?","opts":["It probably wants the watch to seem high-quality.","It made a mistake when setting the price.","It expects to sell more watches than its competitors.","It is trying to attract customers looking for bargains."]}]}', '[1,1,0,2,0]', '["«This practice, known as charm pricing, is so common that many shoppers no longer notice it» — покупатели не замечают саму практику, то есть charm pricing.","Мы читаем слева направо, и первая цифра производит самое сильное впечатление (the first digit makes the strongest impression).","Пример с платьем доказывает силу «девятки»: цена $39 продавала лучше, чем более низкая $34. D прямо противоречит примеру.","Про удобство для кассиров в тексте ничего нет. Остальные три причины названы в абзаце 3.","Круглая цена, по тексту, — сигнал качества и уверенности, так делают люксовые бренды. Значит, магазин, скорее всего, хочет, чтобы часы выглядели престижно."]', '["Reference","Factual","Rhetorical Purpose","Negative Factual","Inference"]', 0, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-001', 'R', 'rap', 'C', '{"topic":"Life sciences","title":"How Migrating Birds Find Their Way","paras":[["Each autumn, millions of migratory birds travel thousands of kilometers to wintering grounds they may never have seen before, often flying at night and over open ocean.","How they find their way has puzzled biologists for more than a century."],["Experiments have shown that birds draw on several sources of information.","Some species orient themselves by the position of the sun, compensating for its movement across the sky with an internal clock.","Others learn the patterns of stars that rotate around the North Star, a skill that young birds appear to acquire by watching the night sky before their first migration.","Yet birds kept in windowless rooms still attempt to fly in the correct seasonal direction, which suggests that celestial cues cannot be the whole story."],["The most intriguing candidate is the Earth''s magnetic field.","When researchers placed robins in cages surrounded by artificial magnetic fields, the birds shifted their preferred direction to match the altered field.","Remarkably, this sense appears to depend on light: the response disappeared under certain wavelengths, leading scientists to propose that birds may literally see magnetic fields through specialized molecules in their eyes.","If confirmed, this mechanism would represent one of the most unusual sensory systems known in nature."]],"qs":[{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Birds that cannot see the sky usually fly in the wrong direction during migration.","Celestial cues are the main reason why birds fly in the correct direction each season.","Since birds in rooms without windows still choose the right direction, they must use something besides the sun and stars.","Scientists kept birds in windowless rooms to prevent them from seeing the stars."],"simp":{"p":1,"s":3}},{"type":"Vocabulary","stem":"The word \"intriguing\" in the passage is closest in meaning to","opts":["fascinating","confusing","reliable","obvious"],"hl":{"p":2,"s":0,"w":"intriguing"}},{"type":"Inference","stem":"What can be inferred about young birds before their first migration?","opts":["They already know the position of the North Star from birth.","They need to observe the night sky to learn how to use the stars.","They cannot travel at night.","They follow older birds instead of the stars."]},{"type":"Factual","stem":"According to paragraph 3, what happened when robins were placed in artificial magnetic fields?","opts":["They stopped trying to migrate.","They changed the direction they preferred.","They became unable to see light.","They flew toward the North Star."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention that the response \"disappeared under certain wavelengths\"?","opts":["To show that robins dislike some colors of light","To support the idea that the magnetic sense depends on light","To explain why birds migrate at night","To suggest that the experiment was poorly designed"],"hl":{"p":2,"s":2,"w":"disappeared under certain wavelengths"}}]}', '[2,0,1,1,1]', '["Суть: птицы без доступа к небу всё равно выбирают верное направление → значит, солнце и звёзды — не единственный ориентир. A противоречит оригиналу, B переворачивает вывод, D пересказывает деталь и теряет главное.","Intriguing — интригующий, очень интересный. Confusing — ловушка по созвучию смысла «загадочный», но слово описывает интерес, а не путаницу.","Навык ориентироваться по звёздам молодые птицы, судя по всему, приобретают, наблюдая ночное небо до первой миграции. Значит, это умение не врождённое и требует наблюдения.","«The birds shifted their preferred direction to match the altered field» — сменили предпочтительное направление вслед за изменённым полем.","Факт с длинами волн — доказательство тезиса «this sense appears to depend on light». Вопрос о функции: деталь подкрепляет мысль о связи магнитного чувства со светом."]', '["Sentence Simplification","Vocabulary","Inference","Factual","Rhetorical Purpose"]', 1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-002', 'R', 'rap', 'C', '{"topic":"History","title":"From Tokens to Tablets","paras":[["Writing is often described as a sudden invention, but in Mesopotamia it seems to have developed gradually from practical needs.","Long before the first written texts, farmers and traders used small clay tokens of different shapes to keep track of goods such as grain and livestock."],["Around 3500 BCE, officials began sealing these tokens inside hollow clay containers to guarantee that a shipment had not been altered.","Because a sealed container could not be checked without breaking it, they pressed the tokens into its surface before closing it, leaving visible marks.","Eventually, administrators realized that the marks alone were sufficient.","The tokens themselves could be abandoned, and signs drawn on flat clay tablets took their place."],["Over the following centuries, this system of accounting expanded.","Scribes added signs for numbers and for the names of people, and later used symbols to represent sounds as well as objects.","Only at this point could writing record language in general, including stories, laws, and letters.","The earliest writing, in other words, was not designed to preserve literature but to manage an economy."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"In other words, the outside of the container now recorded exactly what was inside."},"qs":[{"type":"Factual","stem":"According to paragraph 1, what were clay tokens used for?","opts":["Decorating containers","Recording quantities of goods","Writing down stories","Paying taxes to officials"]},{"type":"Reference","stem":"The word \"they\" in paragraph 2 refers to","opts":["tokens","containers","officials","shipments"],"hl":{"p":1,"s":1,"w":"they"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added. Where would the sentence best fit?","insert":true},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following were added to the system EXCEPT:","opts":["signs for numbers","names of people","symbols for sounds","maps of trade routes"]},{"type":"Rhetorical Purpose","stem":"How is the passage organized?","opts":["It compares two competing theories about the origin of writing.","It traces how writing gradually developed from an earlier practice.","It describes a problem and explains why the solution failed.","It argues that writing was invented suddenly by one culture."]}]}', '[1,2,1,3,1]', '["Жетоны использовали «to keep track of goods such as grain and livestock» — вести учёт товаров.","Кто вдавливал жетоны в поверхность сосуда? Люди — officials из предыдущего предложения. Tokens — ловушка: это ближайшее существительное во мн. ч., но жетоны сами себя не вдавливают.","«In other words» пересказывает предыдущую мысль: на поверхности сосуда остались отпечатки жетонов — значит, снаружи было видно, что внутри. Поэтому вставка идёт сразу после предложения про отпечатки (visible marks).","Числа, имена и знаки для звуков названы в абзаце 3. Карт торговых путей в тексте нет.","Текст идёт по этапам: жетоны → запечатанные сосуды с отпечатками → таблички → знаки для звуков. Это последовательное развитие. D противоречит первому предложению."]', '["Factual","Reference","Insert Text","Negative Factual","Rhetorical Purpose"]', 1, 'active', 1793386125506, 1793386125506)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
